<template><div class="page profile-page"><Header/><main><ProfileSidebar /><section class="profile-content"><div><h1>Shipping Address</h1><div v-if="addresses.length===0" class="empty">♢<span>No data available</span></div><article v-for="(a,i) in addresses"><h3>{{a.name}} <small>{{a.label}}</small></h3><p>{{a.phone}}</p><p>{{a.detail}}</p><p class="gray">{{a.region}}</p><footer><label><input type="radio" name="default" :checked="i===0"> Set as default</label><div><a @click="editIndex=i">Edit</a><a class="delete" @click="remove(i)">Delete</a></div></footer></article></div><div class="add"><h1>Add Address</h1><div class="row"><input placeholder="*First Name"><input placeholder="*Last Name"></div><input placeholder="*Street"><input placeholder="*Address"><div class="row"><input placeholder="*City"><input placeholder="*State"></div><div class="row"><input placeholder="*ZIP Code"><input placeholder="*Country"></div><input placeholder="Address Label"><label><input type="checkbox"> Set as default shipping address</label><div class="actions"><button>Cancel</button><button class="save">Save</button></div></div></section></main><div v-if="editIndex!==null" class="mask"><div class="edit-modal"><button class="x" @click="editIndex=null">×</button><h2>Edit address</h2><p>You can edit your shipping address below.</p><div class="row"><input value="Sophia"><input value="Su"></div><div class="row"><input value="e.g., 123 Main Street"><input value="Apt, Suite, Unit, etc."></div><div class="row"><input value="Portland"><input value="OR"></div><div class="row"><input value="156257"><input value="United States"></div><input value="Home"><div class="modal-actions"><button @click="editIndex=null">Cancel</button><button class="save" @click="editIndex=null">Save</button></div></div></div><div v-if="confirmIndex!==null" class="mask"><div class="confirm">Are you sure you want to delete?<div><button @click="confirmIndex=null">Cancel</button><button class="yes" @click="confirmDelete">confirm</button></div></div></div><Footer/></div></template>
